-- Demo upstream warehouse queried by the demo Metabase instance.
--
-- Fact data is generated by views relative to current_date, using a
-- deterministic hash instead of random(): the same date always yields the same
-- numbers. That keeps "last week" / "last 7 days" dashboards populated no matter
-- when the stack is started, and makes re-downloads of the same window
-- byte-for-byte reproducible (which the idempotency demo relies on).

CREATE SCHEMA sales;
CREATE SCHEMA product;
CREATE SCHEMA finance;

-- Deterministic pseudo-random number in [0, 1) derived from a text key.
CREATE FUNCTION public.demo_rand(key text) RETURNS double precision
    LANGUAGE sql IMMUTABLE AS
$$ SELECT ('x' || substr(md5(key), 1, 8))::bit(32)::bigint::double precision / 4294967296.0 $$;

GRANT EXECUTE ON FUNCTION public.demo_rand(text) TO PUBLIC;

-- ---------------------------------------------------------------------------
-- Sales
-- ---------------------------------------------------------------------------
CREATE TABLE sales.products (
    product_id   integer PRIMARY KEY,
    product_name text          NOT NULL,
    category     text          NOT NULL,
    unit_price   numeric(10,2) NOT NULL
);

