CREATE TABLE sales.regions (region text PRIMARY KEY);
INSERT INTO sales.regions VALUES ('North'), ('South'), ('East'), ('West');

CREATE VIEW sales.daily_product_sales AS
SELECT
    d::date                                                   AS sale_date,
    r.region,
    p.product_name,
    p.category,
    q.orders,
    q.units,
    round(q.units * p.unit_price * (1 - q.discount), 2)       AS revenue
FROM generate_series(current_date - 400, current_date - 1, interval '1 day') AS d
CROSS JOIN sales.regions  AS r
CROSS JOIN sales.products AS p
CROSS JOIN LATERAL (
    SELECT
        o.orders,
        o.orders + floor(demo_rand(k || ':u') * o.orders)::int AS units,
        round((demo_rand(k || ':d') * 0.15)::numeric, 2)       AS discount
    FROM (
        SELECT d::date::text || r.region || p.product_id AS k
    ) AS key
    CROSS JOIN LATERAL (
        SELECT 1 + floor(demo_rand(key.k || ':o') * 12)::int AS orders
    ) AS o
) AS q;

-- ---------------------------------------------------------------------------
-- Product usage (long / "tidy" format: one row per account, day and metric)
-- ---------------------------------------------------------------------------
CREATE TABLE product.accounts (
    account_id   text PRIMARY KEY,
    account_name text NOT NULL,
    plan         text NOT NULL,
    seats        integer NOT NULL
);

