CREATE VIEW product.usage_metrics_daily AS
SELECT
    d::date        AS usage_date,
    a.account_id,
    a.account_name,
    a.plan,
    m.metric,
    CASE m.metric
        WHEN 'active_users' THEN floor(a.seats * (0.35 + 0.6 * demo_rand(d::date || a.account_id || 'au')))
        WHEN 'sessions'     THEN floor(a.seats * (0.8 + 2.5 * demo_rand(d::date || a.account_id || 'se')))
        WHEN 'api_calls'    THEN floor(a.seats * (40 + 400 * demo_rand(d::date || a.account_id || 'api')))
        WHEN 'storage_gb'   THEN round((a.seats * 0.8 + (current_date - d::date) * -0.01
                                        + 5 * demo_rand(d::date || a.account_id || 'st'))::numeric, 2)
    END::numeric   AS value
FROM generate_series(current_date - 120, current_date - 1, interval '1 day') AS d
CROSS JOIN product.accounts AS a
CROSS JOIN (VALUES ('active_users'), ('sessions'), ('api_calls'), ('storage_gb')) AS m(metric);

-- ---------------------------------------------------------------------------
-- Finance (static archive; details is nested JSON as produced by the ERP)
-- ---------------------------------------------------------------------------
CREATE TABLE finance.budget_lines (
    line_id        text PRIMARY KEY,
    fiscal_quarter text          NOT NULL,
    period_month   date          NOT NULL,
    department     text          NOT NULL,
    cost_center    text          NOT NULL,
    category       text          NOT NULL,
    budget         numeric(14,2) NOT NULL,
    actual         numeric(14,2),
    details        jsonb         NOT NULL
);

INSERT INTO finance.budget_lines
SELECT
    format('BL-%s-%s-%s', dept.code, to_char(m, 'YYYYMM'), cat.code)                        AS line_id,
    'FY2025-Q4'                                                                               AS fiscal_quarter,
    m::date                                                                                   AS period_month,
    dept.name                                                                                 AS department,
    format('CC-%s-%s', dept.code, cat.code)                                                   AS cost_center,
    cat.name                                                                                  AS category,
    round((cat.base * dept.scale)::numeric, 2)                                                AS budget,
    -- December actuals for one department are not yet booked (NULL) - realistic gap.
    CASE WHEN dept.code = 'MKT' AND extract(month FROM m) = 12 THEN NULL
         ELSE round((cat.base * dept.scale * (0.82 + 0.36 * demo_rand(dept.code || cat.code || m::date)))::numeric, 2)
    END                                                                                       AS actual,
    jsonb_build_object(
        'owner',    jsonb_build_object('name', dept.owner, 'email', lower(replace(dept.owner, ' ', '.')) || '@example.com'),
        'approval', jsonb_build_object(
                        'status',      CASE WHEN extract(month FROM m) = 12 AND dept.code IN ('MKT', 'ENG') THEN 'pending' ELSE 'approved' END,
                        'approved_by', CASE WHEN extract(month FROM m) = 12 AND dept.code IN ('MKT', 'ENG') THEN NULL ELSE 'CFO Office' END,
                        'approved_at', CASE WHEN extract(month FROM m) = 12 AND dept.code IN ('MKT', 'ENG') THEN NULL
                                            ELSE to_char(m - interval '10 days', 'YYYY-MM-DD"T"09:30:00"Z"') END),
        'forecast', jsonb_build_object('next_quarter', round((cat.base * dept.scale * 1.05)::numeric, 2), 'currency', 'USD')
    )                                                                                         AS details
FROM generate_series('2025-10-01'::date, '2025-12-01'::date, interval '1 month') AS m
CROSS JOIN (VALUES
    ('ENG', 'Engineering', 3.0, 'Priya Raman'),
    ('MKT', 'Marketing',   1.6, 'Daniel Okafor'),
    ('SAL', 'Sales',       2.2, 'Mei Tanaka'),
    ('OPS', 'Operations',  1.2, 'Lucas Moreau'),
    ('FIN', 'Finance',     0.7, 'Sara Lindqvist'),
    ('PPL', 'People',      0.8, 'Omar Haddad')
) AS dept(code, name, scale, owner)
CROSS JOIN (VALUES
    ('PAY', 'Payroll',  120000),
    ('SW',  'Software',  18000),
    ('TRV', 'Travel',     9000)
) AS cat(code, name, base);
